using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Snowglow.Editor {
 [InitializeOnLoad] public static class AlpsTowerRoadPlacement {
  const string ScenePath="Assets/Scenes/AlpsTerrainTest.unity",Log="Logs/AlpsTowerRoad/";
  static AlpsTowerRoadPlacement(){EditorApplication.update+=Pending;}
  static void Check(bool ok,string why){if(!ok)throw new InvalidOperationException("Tower road placement: "+why);}
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Pending(){const string request="Logs/AlpsTowerRoad.request";if(!File.Exists(request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;var action=File.ReadAllText(request).Trim();File.Delete(request);Directory.CreateDirectory(Log);try{Check(action=="place"||action=="height"||action=="narrowroad","known action");if(action=="height")Height();else if(action=="narrowroad")NarrowRoad();else Place();}catch(Exception e){File.WriteAllText(Log+"Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static Bounds Bounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>(true);Check(rs.Length>0,"visible geometry");var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
  static Dictionary<string,string> Transforms(Scene scene,Transform tower,Transform floor)=>All<Transform>(scene).Where(t=>t!=tower&&t!=floor).ToDictionary(t=>GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t=>t.localPosition.ToString("F6")+t.localRotation.ToString("F6")+t.localScale.ToString("F6"));
  static bool Clear(MeshCollider tower,Vector3 centre,float y,float halfWidth){
   for(int i=0;i<=52;i++){var p=new Vector3(Mathf.Lerp(-halfWidth,halfWidth,i/52f),y,centre.z);if(tower.Raycast(new Ray(p+Vector3.back*12,Vector3.forward),out _,24)||tower.Raycast(new Ray(p+Vector3.forward*12,Vector3.back),out _,24))return false;}return true;
  }
  static void Place(){
   var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"active test scene");var tower=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-gatetower").transform;var floor=All<MeshFilter>(scene).Single(f=>f.name=="Civic square | tower").transform;
   Check(!File.Exists(Log+"Completed.txt"),"refuse repeated placement");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"),backup=Log+"InMemory-before-"+stamp+".unity";Check(EditorSceneManager.SaveScene(scene,backup,true),"capture current in-memory scene");File.Copy(ScenePath,Log+"Disk-before-"+stamp+".unity");
   var kept=Transforms(scene,tower,floor);var terrain=All<MeshCollider>(scene).Single(c=>c.bounds.size.x>900);var road=All<MeshCollider>(scene).Single(c=>c.name=="North Street and north entry");var collision=tower.GetComponentsInChildren<MeshCollider>().Single();var sourceMesh=collision.sharedMesh;var material=tower.GetComponentsInChildren<MeshRenderer>().SelectMany(r=>r.sharedMaterials).ToArray();
   var centre=new Vector3(0,0,Mathf.Abs(tower.position.x)<2?tower.position.z:66);Check(terrain.Raycast(new Ray(centre+Vector3.up*500,Vector3.down),out var ground,1000),"ground at new position");Check(road.Raycast(new Ray(centre+Vector3.up*500,Vector3.down),out var roadHit,1000),"connected north road");
   try{
    var floorBounds=Bounds(floor.gameObject);floor.position+=new Vector3(centre.x-floorBounds.center.x,ground.point.y+.12f-floorBounds.center.y,centre.z-floorBounds.center.z);
    tower.position+=new Vector3(centre.x-tower.position.x,ground.point.y+.12f-Bounds(tower.gameObject).min.y,centre.z-tower.position.z);
    // Widen along the road's transverse axis, with a modest height increase so
    // the rounded arch clears machinery at the road edges as well as its centre.
    tower.localScale=new Vector3(1,1.15f,1);var b=Bounds(tower.gameObject);tower.position+=Vector3.up*(roadHit.point.y-.01f-b.min.y);
    float clearanceHeight=4.5f;var sourceBounds=new Bounds(tower.transform.position,Vector3.zero);foreach(var r in tower.GetComponentsInChildren<Renderer>())sourceBounds.Encapsulate(r.bounds);
    float roadWidth=Mathf.Min(road.bounds.size.x,road.bounds.size.z);Check(roadWidth>1,"road width sample");float targetWidth=Mathf.Max(sourceBounds.size.x,roadWidth-.5f);float factor=Mathf.Max(1,targetWidth/Mathf.Max(.001f,sourceBounds.size.x));int probes=0;
    while(factor<=5){tower.localScale=new Vector3(factor,1.15f,1);Physics.SyncTransforms();bool clear=true;for(float y=.15f;y<=clearanceHeight+.001f;y+=.15f){probes++;if(!Clear(collision,centre,roadHit.point.y+y,6.5f)){clear=false;break;}}if(clear)break;factor+=.025f;}
    Check(factor<=5,"13m wide by4.5m high clear arch");
    b=Bounds(tower.gameObject);floorBounds=Bounds(floor.gameObject);Check(b.size.x<floorBounds.size.x-1,"tower feet and roof fit plaza width");
    foreach(var building in All<CatalogPlacement>(scene).Where(p=>p.assetId.StartsWith("alps-rebuild-building_"))){var bb=Bounds(building.gameObject);bb.Expand(2);Check(!b.Intersects(bb),"building clearance "+building.name);}
    for(float x=-6;x<=6;x+=1)for(float z=centre.z-9;z<=centre.z+9;z+=1){Check(road.Raycast(new Ray(new Vector3(x,100,z),Vector3.down),out var hit,200),"road support through arch");Check(Mathf.Abs(hit.point.y-roadHit.point.y)<.1f,"continuous road level");}
    var current=Transforms(scene,tower,floor);Check(kept.All(k=>current[k.Key]==k.Value),"all other placements retained");
    Check(EditorSceneManager.SaveScene(scene,ScenePath),"save placement");var finalPosition=tower.position;var finalScale=tower.localScale;var finalFloor=floor.position;scene=EditorSceneManager.OpenScene(ScenePath);tower=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-gatetower").transform;floor=All<MeshFilter>(scene).Single(f=>f.name=="Civic square | tower").transform;collision=tower.GetComponentsInChildren<MeshCollider>().Single();
    Check(tower.position==finalPosition&&tower.localScale==finalScale&&floor.position==finalFloor,"saved transforms");Check(collision.sharedMesh==sourceMesh,"repaired shared mesh and arch collider retained");current=Transforms(scene,tower,floor);Check(kept.All(k=>current[k.Key]==k.Value),"all other transforms retained on reopen");Check(material.SequenceEqual(tower.GetComponentsInChildren<MeshRenderer>().SelectMany(r=>r.sharedMaterials)),"materials retained");Physics.SyncTransforms();for(float y=.15f;y<=4.5f+.001f;y+=.15f)Check(Clear(collision,centre,roadHit.point.y+y,6.5f),"saved physical arch clearance");
    Capture(scene,tower,centre);EditorSceneManager.OpenScene(ScenePath);
    File.WriteAllText(Log+"Validation.txt","PASS: tower and existing civic floor centred on north road at "+centre.ToString("F3")+", immediately beyond roundabout. Tower scale="+finalScale.ToString("F4")+", position="+finalPosition.ToString("F4")+"; floor="+finalFloor.ToString("F4")+". Physical rays from both ends verify13m width (12m road plus .5m each side) at heights .15-4.5m, including save/reopen; continuous road support verified. Tower/plaza fit, >=1m building envelope clearance, all other transforms, repaired meshes/materials, source assets/terrain unchanged. Captured perspective, gameplay isometric and arch-level views. No Play-driving/device test. Probes="+probes);File.WriteAllText(Log+"Completed.txt",DateTime.UtcNow.ToString("o"));
   }catch{File.Copy(backup,ScenePath,true);AssetDatabase.ImportAsset(ScenePath,ImportAssetOptions.ForceSynchronousImport);EditorSceneManager.OpenScene(ScenePath);throw;}
  }
  static void Height(){
   var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"active test scene");var tower=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-gatetower").transform;var floor=All<MeshFilter>(scene).Single(f=>f.name=="Civic square | tower").transform;
   string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"),backup=Log+"InMemory-height-before-"+stamp+".unity";Check(EditorSceneManager.SaveScene(scene,backup,true),"capture current in-memory scene");File.Copy(ScenePath,Log+"Disk-height-before-"+stamp+".unity");
   var oldPos=tower.position;var oldFloor=floor.position;var oldScale=tower.localScale;try{tower.localScale=new Vector3(oldScale.x,oldScale.x,oldScale.z);Physics.SyncTransforms();Check(EditorSceneManager.SaveScene(scene,ScenePath),"save matched-height tower");var expected=tower.localScale;scene=EditorSceneManager.OpenScene(ScenePath);tower=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-gatetower").transform;floor=All<MeshFilter>(scene).Single(f=>f.name=="Civic square | tower").transform;Check(tower.localScale==expected&&tower.position==oldPos&&floor.position==oldFloor,"height scale and alignment retained on reopen");File.WriteAllText(Log+"HeightValidation.txt","PASS: tower height matched width scale. Scale="+tower.localScale.ToString("F4")+", position="+tower.position.ToString("F4")+", floor="+floor.position.ToString("F4")+". X alignment and road placement retained; no other placement changes requested.");}
   catch{File.Copy(backup,ScenePath,true);AssetDatabase.ImportAsset(ScenePath,ImportAssetOptions.ForceSynchronousImport);EditorSceneManager.OpenScene(ScenePath);throw;}
  }
  static void NarrowRoad(){
   var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"active test scene");var road=All<MeshCollider>(scene).Single(c=>c.name=="North Street and north entry");var filter=road.GetComponent<MeshFilter>();Check(filter&&filter.sharedMesh==road.sharedMesh,"road render and collider share mesh");Check(!File.Exists(Log+"RoadCompleted.txt"),"refuse repeated road narrowing");
   string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"),backup=Log+"InMemory-road-before-"+stamp+".unity";Check(EditorSceneManager.SaveScene(scene,backup,true),"capture current in-memory scene");File.Copy(ScenePath,Log+"Disk-road-before-"+stamp+".unity");var source=filter.sharedMesh;var root=road.transform;var originalBounds=road.bounds;var centreX=originalBounds.center.x;var originalWidth=originalBounds.size.x;Check(originalWidth>10&&road.bounds.size.z>100,"north road orientation and width");
   try{
    var mesh=UnityEngine.Object.Instantiate(source);mesh.name="North entry narrowed through tower tunnel";var vertices=mesh.vertices;
    float WidthAt(float z){if(z<46||z>74)return 12;if(z<52)return Mathf.Lerp(12,6,(z-46)/6);if(z<=68)return 6;return Mathf.Lerp(6,12,(z-68)/6);}
    for(int i=0;i<vertices.Length;i++){var p=root.TransformPoint(vertices[i]);float width=WidthAt(p.z);p.x=centreX+(p.x-centreX)*(width/12f);vertices[i]=root.InverseTransformPoint(p);}
    mesh.vertices=vertices;mesh.RecalculateBounds();mesh.RecalculateNormals();string assetPath="Assets/Snowglow/Levels/AlpsTerrainTest/TownMap/NorthEntryTowerApproach.asset";Check(!AssetDatabase.LoadAssetAtPath<Mesh>(assetPath),"new derivative mesh path");AssetDatabase.CreateAsset(mesh,assetPath);filter.sharedMesh=mesh;road.sharedMesh=mesh;Physics.SyncTransforms();
    Check(Mathf.Abs(road.bounds.center.x-centreX)<.001f,"road remains centred on tunnel X axis");Check(Mathf.Abs(road.bounds.size.x-12)<.05f,"outer road width remains unchanged");
    for(float z=54;z<=66;z+=1){var row=vertices.Select(v=>root.TransformPoint(v)).Where(p=>Mathf.Abs(p.z-z)<1.01f).ToArray();Check(row.Length>0,"approach geometry at z="+z);Check(row.Max(p=>p.x)-row.Min(p=>p.x)<6.1f,"narrow tunnel section width at z="+z);}
    var tower=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-gatetower").transform;var arch=tower.GetComponentInChildren<MeshCollider>();Check(arch,"tower arch collider");for(float z=54;z<=66;z+=1)for(float y=.25f;y<=4.5f;y+=.5f){var origin=new Vector3(0,y,z);Check(!arch.Raycast(new Ray(origin+Vector3.left*5,Vector3.right),out _,10)&&!arch.Raycast(new Ray(origin+Vector3.right*5,Vector3.left),out _,10),"road fits tunnel at z="+z+", y="+y);}
    Check(EditorSceneManager.SaveScene(scene,ScenePath),"save narrowed approach");var expected=filter.sharedMesh;scene=EditorSceneManager.OpenScene(ScenePath);road=All<MeshCollider>(scene).Single(c=>c.name=="North Street and north entry");filter=road.GetComponent<MeshFilter>();Check(road.sharedMesh==expected&&filter.sharedMesh==expected,"road mesh saved and reopened");Physics.SyncTransforms();tower=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-gatetower").transform;arch=tower.GetComponentInChildren<MeshCollider>();for(float z=54;z<=66;z+=1)for(float y=.25f;y<=4.5f;y+=.5f){var origin=new Vector3(0,y,z);Check(!arch.Raycast(new Ray(origin+Vector3.left*5,Vector3.right),out _,10)&&!arch.Raycast(new Ray(origin+Vector3.right*5,Vector3.left),out _,10),"reopened road fits tunnel at z="+z+", y="+y);}
    File.WriteAllText(Log+"RoadValidation.txt","PASS: north road is narrowed symmetrically to 6m through the tower approach (z=52-68m), with 12m road transitions at z=46-52m and z=68-74m. The full approach stays centred on X="+centreX.ToString("F3")+". Tower tunnel ray-clearance and matching render/collision mesh references passed before and after save/reopen; original road asset, town layout and other scene placements retained.");File.WriteAllText(Log+"RoadCompleted.txt",DateTime.UtcNow.ToString("o"));
   }catch{File.Copy(backup,ScenePath,true);AssetDatabase.ImportAsset(ScenePath,ImportAssetOptions.ForceSynchronousImport);EditorSceneManager.OpenScene(ScenePath);throw;}
  }
  static void Capture(Scene scene,Transform tower,Vector3 centre){var source=All<Camera>(scene).First();var go=new GameObject("Temporary tower placement review");SceneManager.MoveGameObjectToScene(go,scene);var camera=go.AddComponent<Camera>();camera.CopyFrom(source);camera.enabled=false;camera.aspect=4f/3;camera.farClipPlane=3000;camera.layerCullDistances=new float[32];try{
   var b=Bounds(tower.gameObject);camera.orthographic=false;camera.fieldOfView=55;camera.transform.position=new Vector3(-10,b.min.y+30,centre.z-65);camera.transform.LookAt(new Vector3(0,b.min.y+8,centre.z));Render(camera,Log+"Perspective.png");
   camera.transform.position=new Vector3(0,b.min.y+3,centre.z-22);camera.transform.LookAt(new Vector3(0,b.min.y+3,centre.z+10));Render(camera,Log+"Arch.png");
   var focus=new GameObject("Temporary tower focus");SceneManager.MoveGameObjectToScene(focus,scene);try{focus.transform.position=centre+Vector3.back*15;focus.transform.position+=Vector3.up*b.min.y;var rig=go.AddComponent<CameraRig>();rig.view=camera;rig.terrain=All<Terrain>(scene).Single();rig.SetMode(CameraMode.Isometric);rig.UpdateForTarget(focus.transform,.1f,false);Check(camera.orthographic,"gameplay iso");Render(camera,Log+"GameplayIsometric.png");}finally{UnityEngine.Object.DestroyImmediate(focus);}
  }finally{UnityEngine.Object.DestroyImmediate(go);}}
  static void Render(Camera c,string path){var rt=RenderTexture.GetTemporary(1200,900,24);var prev=RenderTexture.active;var tex=new Texture2D(1200,900,TextureFormat.RGB24,false);try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1200,900),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=prev;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(tex);}}
 }
}
